pseudocode:
fullMonths(a,b) = addMonths(a,k) <= b 인 최대 k (응당일 없으면 말일 규칙)
fullYears(a,b)  = addYears(a,n) <= b 인 최대 n

Y = fullYears(hireDate, baseDate)
M = fullMonths(hireDate, baseDate)
monthlyLeave = monthlyPerfect ? min(11, M) : min(min(11, M), firstYearPerfectMonths)

if (method == "입사일 기준") {
  grants = []
  for (n = 1; addYears(hireDate, n) <= baseDate; n++) {
    base15 = min(25, 15 + floor((n-1)/2))
    // 80% 토글은 마지막(직전) 연 단위 산정기간에만 적용 — 과거 연도에 소급 적용 금지
    g = (!attendance80 && n == Y) ? lowAttendanceMonths : base15
    grants.push({발생일: addYears(hireDate,n), 일수: g})
  }
} else { // 회계연도 기준(1/1)
  grants = []
  firstFY = hireDate 다음의 첫 1월 1일
  lastFY  = baseDate 이전(당일 포함)의 마지막 1월 1일
  for (fy = firstFY; fy <= baseDate; fy = fy + 1년) {
    if (fy == firstFY) {
      prevDays = fy - hireDate            // 입사일~12/31 재직일수
      g = round2(15 * prevDays / 365)     // 표시는 소수 2자리, 부여는 올림 권장
    } else {
      y = fullYears(hireDate, fy)
      base15 = min(25, 15 + floor((y-1)/2))
      // 80% 토글은 마지막 1/1 발생분에만 적용
      g = (y < 1) ? 0 : ((!attendance80 && fy == lastFY) ? lowAttendanceMonths : base15)
    }
    grants.push({발생일: fy, 일수: g})
  }
}
currentGrant = grants.length > 0 ? grants[last].일수 : monthlyLeave
totalAccrued = monthlyLeave + sum(grants.일수)
return { currentGrant, monthlyLeave, totalAccrued, Y, grants }

D = leaveDate - hireDate                       // 일수
if (under15h) return { eligible: false, reason: "초단시간 근로자 적용 제외" }
if (leaveDate < addYears(hireDate, 1))          // 역법 기준 만 1년 판단(윤년 구간에서 D>=365보다 정확)
  return { eligible: false, reason: "계속근로 만 1년 미만" }

periodStart = addMonths(leaveDate, -3)
T = leaveDate - periodStart                     // 89~92일
W = pay3m + annualBonus * 3 / 12 + annualLeavePay * 3 / 12
A = W / T                                       // 소수점 유지
appliedWage = (dailyOrdinary > A) ? dailyOrdinary : A   // 근기법 제2조 제2항
severance = ceil(appliedWage * 30 * D / 365)    // 원 미만 올림
return { D, T, A: round2(A), appliedWage, severance }

R = monthlyOrdinary / monthlyHours              // 통상시급, 소수점 유지
warnings = []
if (R < 10320) warnings.push("통상시급이 2026년 최저임금(10,320원) 미달 소지")

if (under5) {
  otPay = R * otHours; holPay = R * holidayHours; holOverPay = R * holidayOverHours
  nightPay = 0                                   // 가산 자체가 없음
  note = "5인 미만: 가산 없음, 실근로 100%만 지급. 연장근로 한도(제53조)도 미적용"
} else {
  otPay      = R * otHours * 1.5
  holPay     = R * holidayHours * 1.5
  holOverPay = R * holidayOverHours * 2.0
  nightPay   = R * nightHours * 0.5              // 겹침 무관, 가산 50%만
  if (otHours가 주 평균 12h 초과 상당) warnings.push("연장 한도(주 12시간) 초과 위법 소지 — 한도 판단은 1주 총근로 40시간 초과분 기준(대법원 2020도15393), 1일 8시간 초과분 포함 입력이면 오탐 가능")
}
total = ceil(otPay + holPay + holOverPay + nightPay)   // 원 미만 올림
return { R: round2(R), otPay, holPay, holOverPay, nightPay, total, warnings }

if (exUnder3m || exDisaster || exMisconduct) {
  return { duty: false, allowance: 0, note: "해고예고 의무 없음(제26조 단서). 예외③은 노동부령 열거 사유만 해당 — 확대 적용 금지" }
}
N = dismissalDate - noticeDate            // 통보 당일 불산입 → 다음 날부터 예정일까지 일수
dailyOrdinary = monthlyOrdinary / 209 * 8 // 소수점 유지
if (N >= 30) {
  return { duty: true, satisfied: true, allowance: 0, note: "30일 충족. 다툼 방지 위해 31일 이상 여유 권장" }
}
allowance = ceil(dailyOrdinary * 30)      // 30일분 전액, 원 미만 올림
return { duty: true, satisfied: false, N, dailyOrdinary: round2(dailyOrdinary), allowance, note: "해고와 동시 지급" }

weeklyPaidHours = (weeklyHours >= 15) ? weeklyHours + weeklyHours * 8 / 40 : weeklyHours
H = round(weeklyPaidHours * 365 / 7 / 12)      // 주40h → 209
M = basePay + fixedAllowance + monthlyBonus + welfareCash
hourly = M / H                                  // 표시 소수 2자리
canReduce = probation && !contractUnder1y && !simpleLabor
standard = canReduce ? 10320 * 0.9 : 10320      // 9,288 또는 10,320
if (hourly >= standard) {
  return { pass: true, hourly, standard, H, M }
} else {
  shortfall = ceil(standard * H - M)            // 월 부족액, 원 미만 올림
  return { pass: false, hourly, standard, H, M, shortfall,
           note: "미달 약정은 무효 — 차액 지급 의무(동의·합의 무관)" }
}
